import pathlib,subprocess,socket,time,re,json,os,secrets
policy=pathlib.Path('policy.conf').read_text()
grammar=r'\s*filter primary_policy\s*\{\s*bgp_local_pref\s*=\s*(\d+);\s*accept;\s*\}\s*filter standby_policy\s*\{\s*bgp_local_pref\s*=\s*(\d+);\s*accept;\s*\}\s*'
assert re.fullmatch(grammar,policy),'submit the two stated import filters only'
assert os.getuid()!=0,'unprivileged test is required'
before=subprocess.check_output(['ip','-j','route','show','table','all'])
ports=[];reservers=[]
for _ in range(4):
    s=socket.socket();s.bind(('127.0.0.1',0));ports.append(s.getsockname()[1]);reservers.append(s)
for s in reservers:s.close()
prefix='198.18.'+str(secrets.randbelow(200)+1)+'.0/24'
processes=[];logs=[]
def call(node,*args):
    result=subprocess.run(['birdc','-s',node+'.ctl',*args],capture_output=True,text=True,timeout=2)
    assert result.returncode==0 or (args[:3]==('show','route','for') and 'Network not found' in result.stdout),(result.stdout,result.stderr)
    return result.stdout
def await_value(fn,predicate,seconds=5):
    end=time.monotonic()+seconds;value=None
    while time.monotonic()<end:
        assert all(p.poll() is None for p in processes),[pathlib.Path(n+'.log').read_text() for n in ('a','b','c')]
        value=fn()
        if predicate(value):return value
        time.sleep(.03)
    raise AssertionError(value)
def selected(text,name):return any('*' in line and '['+name+' ' in line for line in text.splitlines())
configs={}
for i,node in enumerate(('a','b')):
    prepend='bgp_path.prepend(65199); bgp_path.prepend(65198);' if i==0 else ''
    configs[node]=f"""
log stderr all;
router id 192.0.2.{i+1};
protocol static seed {{ ipv4; route {prefix} blackhole; }}
protocol bgp uplink {{
 local 127.0.0.1 port {ports[i]} as {65001+i};
 neighbor 127.0.0.1 port {ports[2+i]} as 65010;
 multihop; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import none; next hop keep;
 export filter {{ if net = {prefix} then {{ bgp_next_hop=192.0.2.254; {prepend} accept; }} reject; }};
 }};
}}
"""
configs['c']='log stderr all;\nrouter id 192.0.2.10;\ninclude "policy.conf";\nprotocol static igp { ipv4; route 192.0.2.254/32 blackhole; }\n'
for i,name in enumerate(('primary','standby')):
    configs['c']+=f"""
protocol bgp {name} {{
 local 127.0.0.1 port {ports[2+i]} as 65010;
 neighbor 127.0.0.1 port {ports[i]} as {65001+i};
 multihop; passive on; strict bind on; connect retry time 1; connect delay time 1;
 ipv4 {{ import filter {name}_policy; export none; }};
}}
"""
try:
    for node,config in configs.items():
        pathlib.Path(node+'.conf').write_text(config)
        checked=subprocess.run(['bird','-p','-c',node+'.conf'],capture_output=True,text=True,timeout=3)
        assert checked.returncode==0,checked.stderr
    for node in ('c','a','b'):
        handle=open(node+'.log','w');logs.append(handle)
        processes.append(subprocess.Popen(['bird','-f','-c',node+'.conf','-s',node+'.ctl','-P',node+'.pid'],stdout=handle,stderr=handle))
    await_value(lambda:all(pathlib.Path(n+'.ctl').exists() for n in configs),bool)
    both=await_value(lambda:call('c','show','route','for',prefix,'all'),lambda text:'[primary ' in text and '[standby ' in text)
    assert selected(both,'primary'),'higher LOCAL_PREF must beat the shorter standby AS_PATH: '+both
    assert 'BGP.as_path: 65001 65198 65199' in both and 'BGP.as_path: 65002' in both,both
    assert 'BGP.local_pref: 200' in both and 'BGP.local_pref: 100' in both,both
    call('c','disable','primary')
    backup=await_value(lambda:call('c','show','route','for',prefix,'all'),lambda text:selected(text,'standby') and '[primary ' not in text)
    call('c','enable','primary')
    restored=await_value(lambda:call('c','show','route','for',prefix,'all'),lambda text:selected(text,'primary') and '[standby ' in text)
    pathlib.Path('route-observations.json').write_text(json.dumps({'prefix':prefix,'both':both,'withdraw_primary':backup,'restored':restored,'forwarding_verified':False},indent=2))
finally:
    for p in processes:
        if p.poll() is None:p.terminate()
    for p in processes:
        try:p.wait(timeout=2)
        except subprocess.TimeoutExpired:p.kill();p.wait(timeout=2)
    for h in logs:h.close()
    assert before==subprocess.check_output(['ip','-j','route','show','table','all']),'kernel route tables must not change'
